int a[13];

int main() {
    int k;
    scanf("%d", &k);

    for (int i = 1; i <= 12; i++) {
        scanf("%d", &a[i]);
    }

    sort(a + 1, a + 13, greater<int>());

    int ans = 0, cnt = 0;
    for (int i = 1; i <= 12; i++) {
        ans += a[i];
        cnt++;
        if (ans >= k) break;
    }

    if (ans < k) printf("-1");
    else printf("%d", cnt);

    return 0;
}

